INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Attribut immer eine Spalte in einer Datenbank?', 2, '[{"text": "Ja", "correct": true, "because": "Repräsentiert Datenfeld"}, {"text": "Nein", "correct": false, "because": "Kontextabhängig, aber meist Spalte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Attribut?', 3, '[{"text": "Daten beschreiben", "correct": true, "because": "Definiert Eigenschaften"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Kein Sicherheitsfokus"}, {"text": "Speicher sparen", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Attribut in einer Datenbank?', 5, '[{"text": "Name", "correct": true, "because": "Identifiziert Attribut"}, {"text": "Datentyp", "correct": true, "because": "Definiert Format"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Datenbankfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Attribut kann ein Primärschlüssel sein. b) Es muss immer eindeutig sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eindeutigkeit nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Definition eines Attributs?', 4, '[{"text": "Datentyp", "correct": false, "because": "Entscheidend für Format"}, {"text": "Constraints", "correct": false, "because": "Regeln für Werte"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Attribut einen Standardwert haben kann?', 2, '[{"text": "Ja", "correct": true, "because": "Default-Werte möglich"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Attribut ist typischerweise ein Primärschlüssel?', 3, '[{"text": "ID", "correct": true, "because": "Eindeutig und identifizierend"}, {"text": "Name", "correct": false, "because": "Nicht immer eindeutig"}, {"text": "Beschreibung", "correct": false, "because": "Zu variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Definition eines Attributs?', 5, '[{"text": "Datentyp", "correct": true, "because": "z.B. INT, VARCHAR"}, {"text": "Nullability", "correct": true, "because": "NULL erlaubt oder nicht"}, {"text": "Farbe", "correct": false, "because": "Kein Datenbankfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Attribute beschreiben Entitäten. b) Sie sind immer numerisch. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Können auch Text sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Attribut unwichtig?', 4, '[{"text": "Name", "correct": false, "because": "Identifikation nötig"}, {"text": "Datentyp", "correct": false, "because": "Definiert Format"}, {"text": "Anzeigefarbe", "correct": true, "because": "Kein Datenbankaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Attribut mehrere Werte haben?', 2, '[{"text": "Nein", "correct": true, "because": "Ein Wert pro Instanz"}, {"text": "Ja", "correct": false, "because": "Normalisierung verhindert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein gut definiertes Attribut?', 4, '[{"text": "Datenkonsistenz", "correct": true, "because": "Klar definierte Werte"}, {"text": "Einfache Abfragen", "correct": true, "because": "Strukturierte Daten"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Attribute immer Pflichtfelder sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können optional sein"}, {"text": "Ja", "correct": false, "because": "NULL erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Attribut?', 3, '[{"text": "Datentyp", "correct": true, "because": "Bestimmt Verwendung"}, {"text": "Anzeigeformat", "correct": false, "because": "Sekundär"}, {"text": "Speichergröße", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Attribut kann ein Fremdschlüssel sein. b) Es muss immer eindeutig sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eindeutigkeit nicht Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlecht definiertes Attribut?', 5, '[{"text": "Dateninkonsistenz", "correct": true, "because": "Unklare Werte"}, {"text": "Schwierige Abfragen", "correct": true, "because": "Fehlende Struktur"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Attribut unwichtig?', 3, '[{"text": "Name", "correct": false, "because": "Identifikation nötig"}, {"text": "Datentyp", "correct": false, "because": "Format entscheidend"}, {"text": "Anzeigereihenfolge", "correct": true, "because": "Kein Datenbankfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Attribut leer sein?', 3, '[{"text": "Ja", "correct": true, "because": "NULL-Werte erlaubt"}, {"text": "Nein", "correct": false, "because": "Optional möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Attribut einen Index haben kann?', 2, '[{"text": "Ja", "correct": true, "because": "Für schnellere Abfragen"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Attribut wähle ich für eine eindeutige Identifikation?', 4, '[{"text": "Primärschlüssel", "correct": true, "because": "Eindeutig und notwendig"}, {"text": "Beschreibung", "correct": false, "because": "Nicht eindeutig"}, {"text": "Datum", "correct": false, "because": "Kann sich wiederholen"}]');
